const results = [];
const seenLinks = new Set();

const addResult = (link, title, snippet) => {
  if (link && link.includes('linkedin.com/') && !seenLinks.has(link)) {
    seenLinks.add(link);
    results.push({ 
      json: { 
        title: title || "New LinkedIn Post", 
        link: link, 
        snippet: snippet || title || "No context available" 
      } 
    });
  }
};

// 1. Process Organic Results from "HTTP Request" node
const organic = $node["HTTP Request"].json.organic_results;
if (organic && Array.isArray(organic)) {
  organic.forEach(res => {
    addResult(res.link, res.title, res.snippet);
  });
}

// 2. Process Perspectives 
const perspectives = $node["HTTP Request"].json.perspectives;
if (perspectives && Array.isArray(perspectives)) {
  perspectives.forEach(res => {
    const link = res.link || res.link_url || res.url;
    addResult(link, res.title, res.snippet || res.title);
  });
}

return results.slice(0, 3); // Returns top 3 unique posts

const filterResults = $('LinkedIn Filter').all();
const ollamaResults = $('Ollama').all();

// Assuming webhook body has the raw query topic
const topic = $('Webhook').first().json.body.query || 'Unknown Topic';

return ollamaResults.map((item, i) => {
  return {
    json: {
      ID: 'LNK-' + Math.random().toString(36).substr(2, 9).toUpperCase(),
      Topic: topic,
      Title: filterResults[i].json.title,
      Link: filterResults[i].json.link,
      Content: item.json.content,
      Status: 'Pending'
    }
  }
});
